#!/usr/bin/env python3

import sys

BASE36 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def to_base36(n: int) -> str:
    if n == 0:
        return BASE36[0]
    result = []
    while n > 0:
        result.append(BASE36[n % 36])
        n //= 36
    return ''.join(reversed(result))


def from_base36(s: str) -> int:
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch.upper())
    return n


def main() -> None:
    try:
        with open('ids.txt') as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print('ORD-0000', file=sys.stderr)
        sys.exit(1)

    if not lines:
        print('ORD-0000', file=sys.stderr)
        sys.exit(1)

    last_id = lines[-1]
    suffix = last_id.split('-')[1]  # e.g. '243G'
    num = from_base36(suffix)
    next_num = num + 1
    next_suffix = to_base36(next_num).zfill(4).upper()
    print(f'ORD-{next_suffix}')


if __name__ == '__main__':
    main()

