#!/usr/bin/env python3
"""Generate the next order id.

Reads ids.txt from the current directory (one order id per line, most recent last)
and prints the next order id to stdout followed by a newline.

Ids have the form ORD- followed by four characters (0-9, A-Z).
"""

import sys

CHARS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
BASE = len(CHARS)  # 36


def _to_int(suffix: str) -> int:
    value = 0
    for ch in suffix:
        value = value * BASE + CHARS.index(ch)
    return value


def _from_int(value: int, width: int = 4) -> str:
    result = ""
    for _ in range(width):
        result = CHARS[value % BASE] + result
        value //= BASE
    return result


def next_id(last_id: str) -> str:
    prefix = last_id[:4]  # "ORD-"
    suffix = last_id[4:]  # e.g. "243G"
    return prefix + _from_int(_to_int(suffix) + 1)


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    last_id = lines[-1]
    print(next_id(last_id))


if __name__ == "__main__":
    main()

