import sys

ID_FILE = "ids.txt"
CHARS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def next_id(current_id: str) -> str:
    """Generate the next order ID by incrementing the alphanumeric suffix."""
    prefix = current_id[:4]  # "ORD-"
    suffix = list(current_id[4:])  # four characters after "ORD-"

    # Increment from rightmost character, with carry-over
    for i in range(len(suffix) - 1, -1, -1):
        idx = CHARS.index(suffix[i])
        if idx < len(CHARS) - 1:
            suffix[i] = CHARS[idx + 1]
            break
        else:
            suffix[i] = CHARS[0]  # wrap to '0' and carry
    else:
        # All characters wrapped — prefix with '1' (overflow)
        suffix = list("1000")
        # Could also raise, but this is a practical fallback

    return prefix + "".join(suffix)


def main():
    try:
        with open(ID_FILE) as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        # No ids issued yet — start from the first id
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    last_id = lines[-1]
    print(next_id(last_id))


if __name__ == "__main__":
    main()

