#!/usr/bin/env python3

import sys

def next_id(prev_id):
    """Increment a 4-character base-36 ID and return the next one."""
    # Extract the last 4 characters after "ORD-"
    suffix = prev_id[-4:]

    # Convert from base-36 to integer
    # Base-36 uses digits 0-9 and letters A-Z
    val = 0
    for ch in suffix:
        if '0' <= ch <= '9':
            val = val * 36 + (ord(ch) - ord('0'))
        elif 'A' <= ch <= 'Z':
            val = val * 36 + (ord(ch) - ord('A') + 10)
        else:
            raise ValueError(f"Invalid character in ID: {ch}")

    # Increment
    val += 1

    # Convert back to base-36, padded to 4 characters
    result = []
    for _ in range(4):
        remainder = val % 36
        if remainder < 10:
            result.append(chr(ord('0') + remainder))
        else:
            result.append(chr(ord('A') + remainder - 10))
        val //= 36
    suffix = ''.join(reversed(result))

    return f"ORD-{suffix}"

def main():
    try:
        with open('ids.txt', 'r') as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("Error: ids.txt not found", file=sys.stderr)
        sys.exit(1)

    if not lines:
        print("Error: ids.txt is empty", file=sys.stderr)
        sys.exit(1)

    # The last line is the most recent ID
    last_id = lines[-1]
    new_id = next_id(last_id)
    print(new_id)

if __name__ == '__main__':
    main()

