#!/usr/bin/env python3
"""Read ids.txt and print the next sequential order id."""

import pathlib


def base36_encode(n: int, width: int) -> str:
    """Encode integer n as a base-36 string, zero-padded to width."""
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = ""
    for _ in range(width):
        n, rem = divmod(n, 36)
        result = digits[rem] + result
    return result


def main() -> None:
    lines = pathlib.Path("ids.txt").read_text().splitlines()
    # Find the last non-empty line
    last_id = ""
    for line in reversed(lines):
        line = line.strip()
        if line:
            last_id = line
            break

    if not last_id:
        raise SystemExit("error: ids.txt is empty or missing")

    if not last_id.startswith("ORD-") or len(last_id) != 8:
        raise SystemExit(f"error: unexpected id format: {last_id!r}")

    suffix = last_id[4:]  # e.g., "243G"
    current = int(suffix, 36)
    next_suffix = base36_encode(current + 1, 4)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

