#!/usr/bin/env python3
"""Read attendees.txt (UTF-8, one name per line) and write roster.txt
with the same names sorted alphabetically, one per line."""

import os

def main() -> None:
    # Read names from attendees.txt, skipping blank lines
    names: list[str] = []
    with open("attendees.txt", encoding="utf-8") as f:
        for line in f:
            stripped = line.strip()
            if stripped:
                names.append(stripped)

    # Sort alphabetically (case-sensitive, per typical name sorting)
    names.sort()

    # Write sorted names to roster.txt
    with open("roster.txt", "w", encoding="utf-8") as f:
        for name in names:
            f.write(name + "\n")

if __name__ == "__main__":
    main()

