"""Register the current version in releases.log.

Reads VERSION, checks whether it is already recorded in releases.log,
and appends it if not.  Idempotent by design so that re-running the
deploy pipeline does not create duplicate entries.
"""

from __future__ import annotations


def main() -> None:
    with open("VERSION") as f:
        version = f.read().strip()

    if not version:
        msg = "VERSION is empty"
        raise SystemExit(msg)

    try:
        with open("releases.log") as f:
            existing = {line.strip() for line in f}
    except FileNotFoundError:
        existing = set()

    if version in existing:
        return

    with open("releases.log", "a") as f:
        f.write(version + "\n")


if __name__ == "__main__":
    main()

