#!/usr/bin/env python3
"""Print file names under reports/ in report order, one per line."""

import os
import re

REPORTS_DIR = os.path.join(os.path.dirname(__file__), "reports")


def report_sort_key(filename: str) -> tuple:
    """Sort by numeric part in filename for natural ordering."""
    match = re.search(r"(\d+)", filename)
    return (int(match.group(1)) if match else 0, filename)


def main() -> None:
    if not os.path.isdir(REPORTS_DIR):
        return

    files = [f for f in os.listdir(REPORTS_DIR) if os.path.isfile(os.path.join(REPORTS_DIR, f))]
    files.sort(key=report_sort_key)

    for f in files:
        print(f)


if __name__ == "__main__":
    main()
