#!/usr/bin/env python3
"""Count word occurrences in all .txt files under docs/."""

import glob
import os
from collections import Counter

punctuation = set(".,;:!?")

counts = Counter()

for txt_path in sorted(glob.glob("docs/**/*.txt", recursive=True)):
    with open(txt_path, encoding="utf-8") as f:
        for line in f:
            for raw_word in line.split():
                word = raw_word.lower().strip("".join(punctuation))
                if word:
                    counts[word] += 1

with open("counts.txt", "w", encoding="utf-8") as out:
    for word in sorted(counts):
        out.write(f"{word} {counts[word]}\n")

