#!/usr/bin/env python3
"""Count occurrences of each word in all .txt files under docs/."""

import os
import re
from collections import Counter

PUNCTUATION = set(".,;:!?")
DOCS_DIR = "docs"
OUTPUT_FILE = "counts.txt"


def word_generator():
    """Yield normalized words from every .txt file under DOCS_DIR."""
    for root, _dirs, files in os.walk(DOCS_DIR):
        for fn in files:
            if not fn.endswith(".txt"):
                continue
            path = os.path.join(root, fn)
            with open(path, encoding="utf-8") as f:
                for line in f:
                    for raw in line.split():
                        word = raw.lower().strip("".join(PUNCTUATION))
                        if word:
                            yield word


def main() -> int:
    counter = Counter()

    try:
        for word in word_generator():
            counter[word] += 1
    except FileNotFoundError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1

    with open(OUTPUT_FILE, "w", encoding="utf-8") as f:
        for word in sorted(counter):
            f.write(f"{word} {counter[word]}\n")

    return 0


if __name__ == "__main__":
    main()

