"""
count_words.py

Read every .txt file under docs/, lowercase each word, strip punctuation
.,;:!? from word edges, count occurrences, and write counts.txt.
"""

import os
import glob


def strip_punctuation(word):
    """Strip punctuation characters .,;:!? from the edges of a word."""
    chars = set('.,;:!?')
    # Strip from the left edge
    while word and word[0] in chars:
        word = word[1:]
    # Strip from the right edge
    while word and word[-1] in chars:
        word = word[:-1]
    return word


def main():
    counts = {}

    # Find all .txt files under docs/
    pattern = os.path.join('docs', '**', '*.txt')
    for filepath in glob.glob(pattern, recursive=True):
        with open(filepath, 'r', encoding='utf-8') as f:
            for line in f:
                for raw_word in line.split():
                    word = strip_punctuation(raw_word.lower())
                    if word:
                        counts[word] = counts.get(word, 0) + 1

    # Write counts.txt sorted alphabetically by word
    with open('counts.txt', 'w', encoding='utf-8') as f:
        for word in sorted(counts):
            f.write(f'{word} {counts[word]}\n')


if __name__ == '__main__':
    main()

