#!/usr/bin/env python3
"""Read every .csv under data/ (columns date,id,amount), combine rows, write report.csv sorted by date."""

from pathlib import Path

CSV_DIR = Path("data")
OUTPUT = Path("report.csv")
HEADER = "date,id,amount\n"


def main() -> None:
    rows: list[str] = []

    for csv_file in sorted(CSV_DIR.glob("*.csv")):
        with open(csv_file) as f:
            # skip header
            lines = f.readlines()
            for line in lines[1:]:
                line = line.strip()
                if line:
                    rows.append(line)

    rows.sort(key=lambda r: r.split(",")[0])  # sort by date (first column)

    with open(OUTPUT, "w", newline="") as f:
        f.write(HEADER)
        for row in rows:
            f.write(row + "\n")


if __name__ == "__main__":
    main()

