import sys
import datetime

def parse_line(line):
    """Parse a line from app.log. Returns (datetime_obj, full_line) or None."""
    line = line.rstrip('\n')
    if len(line) < 19 or line[10] != ' ' or line[4] != '-' or line[7] != '-':
        return None
    try:
        ts = datetime.datetime.strptime(line[:19], '%Y-%m-%d %H:%M:%S')
        return ts, line
    except ValueError:
        return None

def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    threshold = as_of - 7 * 86400  # 7 days in seconds

    # Read all lines from app.log
    try:
        with open('app.log', 'r') as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found", file=sys.stderr)
        sys.exit(1)

    archive_entries = []
    app_entries = []

    for line in lines:
        parsed = parse_line(line)
        if parsed is None:
            # Lines without a valid timestamp go to app.log (keep them)
            app_entries.append(line)
        else:
            ts, _ = parsed
            ts_unix = ts.timestamp()
            if ts_unix < threshold:
                archive_entries.append(line)
            else:
                app_entries.append(line)

    # Append to archive.log
    with open('archive.log', 'a') as f:
        for entry in archive_entries:
            f.write(entry)

    # Rewrite app.log
    with open('app.log', 'w') as f:
        for entry in app_entries:
            f.write(entry)

if __name__ == '__main__':
    main()
